1	import { copyFileSync, mkdirSync, readFileSync } from 'node:fs';
2	import { join, resolve } from 'node:path';
3	import { CostMeter, createRouter, initTracing, shutdownTracing, traced, type ModelClient } from '@dailies/agent';
4	import { DEFAULT_BUDGET, loadEnv, type Env, type RenderArtifact } from '@dailies/core';
5	import { buildStages, createRun, getRun, listEvents, openDb, runPipeline, type StageDeps } from '@dailies/pipeline';
6	import { createGeminiTts, type TtsProvider } from '@dailies/voice';
7	
8	const EVENT_POLL_MS = 50;
9	
10	export interface RunOverrides {
11	  client?: ModelClient;
12	  env?: Env;
13	  stdout?: (line: string) => void;
14	}
15	
16	interface RunArgs {
17	  repoUrl: string;
18	  since?: string;
19	  maxSessions?: number;
20	  out?: string;
21	  noVoice: boolean;
22	  noReview: boolean;
23	}
24	
25	export const RUN_USAGE = 'usage: dailies run <repo-url|path> [--since 24h|<ISO>] [--max-sessions N] [--out <dir>] [--no-voice] [--no-review]';
26	
27	export function parseRunArgs(argv: string[]): RunArgs {
28	  const positional: string[] = [];
29	  let since: string | undefined;
30	  let maxSessions: number | undefined;
31	  let out: string | undefined;
32	  let noVoice = false;
33	  let noReview = false;
34	
35	  for (let i = 0; i < argv.length; i += 1) {
36	    const arg = argv[i]!;
37	    if (arg === '--since') since = argv[(i += 1)];
38	    else if (arg === '--max-sessions') maxSessions = Number(argv[(i += 1)]);
39	    else if (arg === '--out') out = argv[(i += 1)];
40	    else if (arg === '--no-voice') noVoice = true;
41	    else if (arg === '--no-review') noReview = true;
42	    else positional.push(arg);
43	  }
44	
45	  const repoUrl = positional[0];
46	  if (!repoUrl) throw new Error(RUN_USAGE);
47	  return { repoUrl, since, maxSessions, out, noVoice, noReview };
48	}
49	
50	/** `<n>h` and `<n>d` relative to `now`; anything else is parsed as an ISO date. */
51	export function parseSince(value: string, now: Date): string {
52	  const relative = /^(\d+)([hd])$/.exec(value);
53	  if (relative) {
54	    const amount = Number(relative[1]);
55	    const ms = amount * (relative[2] === 'h' ? 3_600_000 : 86_400_000);
56	    return new Date(now.getTime() - ms).toISOString();
57	  }
58	  const parsed = new Date(value);
59	  if (Number.isNaN(parsed.getTime())) throw new Error(`invalid --since value: ${value}`);
60	  return parsed.toISOString();
61	}
62	
63	/** A stage's own artifact, read the way the runner writes it. Null when the stage never ran. */
64	function readStageArtifact<T>(dataDir: string, runId: string, stage: string): T | null {
65	  try {
66	    return JSON.parse(readFileSync(join(dataDir, 'runs', runId, `${stage}.json`), 'utf8')) as T;
67	  } catch {
68	    return null;
69	  }
70	}
71	
72	function exitCodeFor(status: string): number {
73	  if (status === 'needs_approval') return 0;
74	  if (status === 'blocked') return 2;
75	  return 1;
76	}
77	
78	// The conservative fallback: everything up to the last "@" before the first "/", for a URL
79	// that carries a credential but is too malformed for `new URL()` to accept at all (an invalid
80	// port, for instance) — a parser that rejects the URL must not be the reason a credential in it
81	// survives. Run unconditionally, including after a successful parse, as a second pass that does
82	// not depend on `URL`'s own idea of what counts as userinfo.
83	const USERINFO = /^([a-z][a-z0-9+.-]{0,31}:\/\/)[^\s/]*@/i;
84	
85	/**
86	 * `url` with any userinfo removed. Stripped before a repository URL reaches tracing input — a
87	 * run is only ever of a public repository, but a credential pasted into the URL by mistake must
88	 * not be the one place that escapes ingest's own redaction and lands in a trace unredacted. A
89	 * string that is not a URL at all (a local path, an SCP-style `git@host:path`, which carries no
90	 * embedded secret) is returned unchanged.
91	 */
92	export function stripUserinfo(url: string): string {
93	  let cleaned = url;
94	  try {
95	    const parsed = new URL(url);
96	    parsed.username = '';
97	    parsed.password = '';
98	    cleaned = parsed.toString();
99	  } catch {
100	    // Not a URL `new URL()` will accept — fall through to the regex pass below rather than
101	    // returning the original string unexamined.
102	  }
103	  return cleaned.replace(USERINFO, '$1');
104	}
105	
106	// Event messages, reasons and claim text ultimately derive from a third-party repository's
107	// commits and agent transcripts — untrusted input by design. Printed to a terminal as-is, a
108	// control character (an escape sequence, a stray carriage return) could spoof or hide output;
109	// a Unicode format or separator character (a bidi override, a zero-width joiner) could do the
110	// same without ever touching the C0/C1 range. `\` is escaped too, so the escaped text can always
111	// be told apart from a literal backslash that was already in the input.
112	const UNSAFE_CHARS = /\\|[\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/gu;
113	export function sanitizeForTerminal(text: string): string {
114	  return text.replace(UNSAFE_CHARS, (c) => (c === '\\' ? '\\\\' : `\\u{${c.codePointAt(0)!.toString(16)}}`));
115	}
116	
117	export async function runCommand(argv: string[], overrides: RunOverrides = {}): Promise<number> {
118	  const args = parseRunArgs(argv);
119	  const env = overrides.env ?? loadEnv();
120	  const stdout = overrides.stdout ?? ((line: string) => console.log(line));
121	
122	  let client = overrides.client;
123	  if (!client && !env.gatewayKey) {
124	    console.error('LITELLM_API_KEY is not set');
125	    return 1;
126	  }
127	
128	  const until = new Date();
129	  const since = parseSince(args.since ?? '24h', until);
130	
131	  mkdirSync(env.dataDir, { recursive: true });
132	  const db = openDb(join(env.dataDir, 'db.sqlite'));
133	  const runId = createRun(db, { repoUrl: args.repoUrl, since, until: until.toISOString(), budget: DEFAULT_BUDGET });
134	
135	  const meter = new CostMeter(DEFAULT_BUDGET.maxCostPerReelUsd);
136	  client = client ?? createRouter(env, meter);
137	  const tts: TtsProvider | null = args.noVoice || env.geminiKeys.length === 0 ? null : createGeminiTts(env.geminiKeys);
138	
139	  await initTracing(env, 'dailies-reel');
140	  try {
141	    const status = await traced('WORKFLOW', 'dailies-reel', async (input: { repoUrl: string; runId: string }) => {
142	      const deps: StageDeps = { db, client: client!, meter, tts, voice: 'Charon', maxSessions: args.maxSessions };
143	      // `reviewStage` is not exported from `@dailies/pipeline` (only its artifact type is), so there is no
144	      // way into it through the package's one allowed door. `--no-review` is accepted for the documented
145	      // command surface, but there is currently nothing for it to switch off: buildStages' eight stages,
146	      // unmodified, are what every run executes either way.
147	      void args.noReview;
148	      const stages = buildStages(deps);
149	
150	      let afterId = 0;
151	      const flush = () => {
152	        for (const event of listEvents(db, input.runId, afterId)) {
153	          stdout(`[${sanitizeForTerminal(event.stage ?? 'run')}] ${sanitizeForTerminal(event.message)}`);
154	          afterId = event.id;
155	        }
156	      };
157	      const timer = setInterval(flush, EVENT_POLL_MS);
158	      try {
159	        return await runPipeline(db, input.runId, stages, { dataDir: env.dataDir });
160	      } finally {
161	        clearInterval(timer);
162	        flush();
163	      }
164	    })({ repoUrl: stripUserinfo(args.repoUrl), runId });
165	
166	    const run = getRun(db, runId);
167	    stdout(`status: ${status}`);
168	    if (run.reason) stdout(`reason: ${sanitizeForTerminal(run.reason)}`);
169	    stdout(`cost: $${run.costUsd.toFixed(4)}`);
170	
171	    const render = readStageArtifact<RenderArtifact>(env.dataDir, runId, 'render');
172	    if (render) {
173	      let { videoPath, srtPath, posterPath } = render;
174	      if (args.out) {
175	        const outDir = resolve(args.out);
176	        mkdirSync(outDir, { recursive: true });
177	        const copyInto = (src: string, name: string): string => {
178	          const dest = join(outDir, name);
179	          copyFileSync(src, dest);
180	          return dest;
181	        };
182	        videoPath = copyInto(videoPath, 'reel.mp4');
183	        srtPath = copyInto(srtPath, 'reel.srt');
184	        posterPath = copyInto(posterPath, 'poster.png');
185	      }
186	      stdout(`video: ${videoPath}`);
187	      stdout(`subtitles: ${srtPath}`);
188	      stdout(`poster: ${posterPath}`);
189	    }
190	
191	    return exitCodeFor(status);
192	  } finally {
193	    await shutdownTracing();
194	  }
195	}
