1	import { mkdirSync, readFileSync } from 'node:fs';
2	import { join } from 'node:path';
3	import { CostMeter, createRouter, type ModelClient } from '@dailies/agent';
4	import { DEFAULT_BUDGET, loadEnv, type Claim, type Env } from '@dailies/core';
5	import { buildStages, createRun, getRun, openDb, runPipeline, type StageDeps } from '@dailies/pipeline';
6	import { parseSince, sanitizeForTerminal } from './run';
7	
8	export interface VerifyOverrides {
9	  client?: ModelClient;
10	  env?: Env;
11	  stdout?: (line: string) => void;
12	}
13	
14	interface VerifyArgs {
15	  repoUrl: string;
16	  since?: string;
17	  json: boolean;
18	}
19	
20	export const VERIFY_USAGE = 'usage: dailies verify <repo-url|path> [--since 24h|<ISO>] [--json]';
21	
22	export function parseVerifyArgs(argv: string[]): VerifyArgs {
23	  const positional: string[] = [];
24	  let since: string | undefined;
25	  let json = false;
26	
27	  for (let i = 0; i < argv.length; i += 1) {
28	    const arg = argv[i]!;
29	    if (arg === '--since') since = argv[(i += 1)];
30	    else if (arg === '--json') json = true;
31	    else positional.push(arg);
32	  }
33	
34	  const repoUrl = positional[0];
35	  if (!repoUrl) throw new Error(VERIFY_USAGE);
36	  return { repoUrl, since, json };
37	}
38	
39	/** A stage's own artifact, read the way the runner writes it. Null when the stage never ran. */
40	function readStageArtifact<T>(dataDir: string, runId: string, stage: string): T | null {
41	  try {
42	    return JSON.parse(readFileSync(join(dataDir, 'runs', runId, `${stage}.json`), 'utf8')) as T;
43	  } catch {
44	    return null;
45	  }
46	}
47	
48	const cut = (text: string, max: number): string => (text.length <= max ? text : `${text.slice(0, max - 1)}…`);
49	
50	/**
51	 * Runs ingest and the verify stage only, through the same `buildStages` composition `run` uses — the
52	 * verify stage itself is not exported from `@dailies/pipeline` (only through this one way in), and
53	 * reusing it here avoids a second copy of claim extraction and its prompt.
54	 */
55	export async function verifyCommand(argv: string[], overrides: VerifyOverrides = {}): Promise<number> {
56	  const args = parseVerifyArgs(argv);
57	  const env = overrides.env ?? loadEnv();
58	  const stdout = overrides.stdout ?? ((line: string) => console.log(line));
59	
60	  let client = overrides.client;
61	  if (!client && !env.gatewayKey) {
62	    console.error('LITELLM_API_KEY is not set');
63	    return 1;
64	  }
65	
66	  const until = new Date();
67	  const since = parseSince(args.since ?? '24h', until);
68	
69	  mkdirSync(env.dataDir, { recursive: true });
70	  const db = openDb(join(env.dataDir, 'db.sqlite'));
71	  const runId = createRun(db, { repoUrl: args.repoUrl, since, until: until.toISOString(), budget: DEFAULT_BUDGET });
72	
73	  const meter = new CostMeter(DEFAULT_BUDGET.maxCostPerReelUsd);
74	  client = client ?? createRouter(env, meter);
75	  const deps: StageDeps = { db, client, meter, tts: null, voice: 'Charon' };
76	  const stages = buildStages(deps).filter((stage) => stage.name === 'ingest' || stage.name === 'verify');
77	
78	  const status = await runPipeline(db, runId, stages, { dataDir: env.dataDir });
79	  const run = getRun(db, runId);
80	
81	  if (status === 'blocked') {
82	    stdout(sanitizeForTerminal(run.reason ?? 'blocked'));
83	    return 2;
84	  }
85	  if (status === 'failed') {
86	    stdout(sanitizeForTerminal(run.reason ?? 'failed'));
87	    return 1;
88	  }
89	
90	  const claims = readStageArtifact<{ claims: Claim[] }>(env.dataDir, runId, 'verify')?.claims ?? [];
91	
92	  if (args.json) {
93	    stdout(JSON.stringify(claims));
94	    return 0;
95	  }
96	
97	  stdout(['verdict', 'kind', 'session', 'quote', 'reason'].join('\t'));
98	  for (const claim of claims) {
99	    const row = [claim.verdict ?? 'unverifiable', claim.kind, claim.sessionId, cut(claim.quote, 80), claim.reason ?? ''];
100	    stdout(row.map(sanitizeForTerminal).join('\t'));
101	  }
102	  return 0;
103	}
