1	import { RUN_USAGE, runCommand } from './run';
2	import { VERIFY_USAGE, verifyCommand } from './verify';
3	
4	export { runCommand, type RunOverrides } from './run';
5	export { verifyCommand, type VerifyOverrides } from './verify';
6	
7	async function main(): Promise<number> {
8	  const [command, ...rest] = process.argv.slice(2);
9	  if (command === 'run') return runCommand(rest);
10	  if (command === 'verify') return verifyCommand(rest);
11	  console.error(`${RUN_USAGE}\n${VERIFY_USAGE}`);
12	  return 1;
13	}
14	
15	const isMain = import.meta.url === `file://${process.argv[1]}`;
16	if (isMain) {
17	  main()
18	    .then((code) => {
19	      process.exitCode = code;
20	    })
21	    .catch((err: unknown) => {
22	      console.error(err instanceof Error ? err.message : String(err));
23	      process.exitCode = 1;
24	    });
25	}
