1	import { existsSync, mkdtempSync, readFileSync, rmSync } from 'node:fs';
2	import { tmpdir } from 'node:os';
3	import { join } from 'node:path';
4	import { afterEach, describe, expect, it } from 'vitest';
5	import { createMockClient, type ChatMessage, type Role } from '@dailies/agent';
6	import type { Env } from '@dailies/core';
7	import type { GateArtifact, GroundArtifact } from '@dailies/pipeline';
8	import { makeRepo, type FixtureSession } from '../../ingest/test/fixture';
9	import { runCommand, sanitizeForTerminal, stripUserinfo } from '../src/run';
10	import { verifyCommand } from '../src/verify';
11	
12	const dirs: string[] = [];
13	afterEach(() => {
14	  for (const dir of dirs.splice(0)) rmSync(dir, { recursive: true, force: true });
15	});
16	
17	function scratchDataDir(): string {
18	  const dir = mkdtempSync(join(tmpdir(), 'dailies-cli-e2e-'));
19	  dirs.push(dir);
20	  return dir;
21	}
22	
23	function testEnv(dataDir: string): Env {
24	  return { neatlogsApiKey: null, neatlogsEndpoint: 'https://ingest.neatlogs.com', gatewayKey: null, gatewayBaseUrl: '', veniceKey: null, geminiKeys: [], dataDir };
25	}
26	
27	const FAILED_TEST_OUTPUT = '1 failed, 0 passed';
28	const PASSED_TEST_OUTPUT = '3 passed';
29	
30	/** A session that runs `pnpm test`, then claims, in a final message, that it passed. */
31	function testSession(o: { sessionId: string; createdAt: string; prompt: string; outcome: 'fail' | 'pass'; claim: string }): FixtureSession {
32	  return {
33	    sessionId: o.sessionId,
34	    createdAt: o.createdAt,
35	    lines: [
36	      { type: 'user', content: [{ text: o.prompt }] },
37	      {
38	        type: 'assistant',
39	        content: [
40	          {
41	            type: 'tool_use',
42	            id: 't1',
43	            name: 'Bash',
44	            input: { command: 'pnpm test' },
45	            result: { output: o.outcome === 'fail' ? FAILED_TEST_OUTPUT : PASSED_TEST_OUTPUT, status: o.outcome === 'fail' ? 'error' : 'success' },
46	          },
47	        ],
48	      },
49	      { type: 'assistant', content: [{ type: 'text', text: o.claim }] },
50	    ],
51	  };
52	}
53	
54	// Entries land at indexes 0 (user), 1 (tool_call), 2 (tool_result), 3 (assistant claim) — see transcript.ts.
55	const LIAR_SESSION_ID = 's1';
56	const HONEST_SESSION_ID = 's2';
57	const LIE = 'The queue test now passes.';
58	const TRUTH = 'The health check test now passes.';
59	
60	/** One checkpoint per session, the way `packages/pipeline/test/stages/ingest.test.ts` builds its fixtures. */
61	async function fixtureRepo(sessions: FixtureSession[]): Promise<string> {
62	  const dir = await makeRepo({ layout: 'refs', checkpoints: sessions.map((s, n) => ({ id: `ab${n}234ef`, sessions: [s] })) });
63	  dirs.push(dir);
64	  return dir;
65	}
66	
67	/** The two-session fixture: one session lies about a failed test run, the other is honest. */
68	function liarAndHonestSessions(): FixtureSession[] {
69	  return [
70	    testSession({ sessionId: LIAR_SESSION_ID, createdAt: '2026-10-10T07:00:00Z', prompt: 'Fix the flaky queue test.', outcome: 'fail', claim: LIE }),
71	    testSession({ sessionId: HONEST_SESSION_ID, createdAt: '2026-10-10T09:00:00Z', prompt: 'Add a health check endpoint.', outcome: 'pass', claim: TRUTH }),
72	  ];
73	}
74	
75	type MockRequest = { role: Role; messages: ChatMessage[] };
76	const json = (value: unknown): ChatMessage => ({ role: 'assistant', content: JSON.stringify(value) });
77	const text = (messages: ChatMessage[]): string =>
78	  messages.filter((m) => m.role === 'system' || m.role === 'user').map((m) => (typeof m.content === 'string' ? m.content : '')).join('\n');
79	
80	/** Scripted replies for every role the run exercises, tuned to `liarAndHonestSessions()`. */
81	function reply(req: MockRequest): ChatMessage {
82	  const told = text(req.messages);
83	
84	  if (req.role === 'editor') {
85	    return json({
86	      beats: [
87	        { kind: 'fix', title: 'Fix the flaky queue test', summary: 'The agent looked at the queue test.', sessionIds: [LIAR_SESSION_ID], entryRanges: [{ sessionId: LIAR_SESSION_ID, from: 0, to: 3 }], commits: [] },
88	        { kind: 'feature', title: 'Add a health check endpoint', summary: 'The agent added a health check.', sessionIds: [HONEST_SESSION_ID], entryRanges: [{ sessionId: HONEST_SESSION_ID, from: 0, to: 3 }], commits: [] },
89	      ],
90	    });
91	  }
92	
93	  if (req.role === 'extractor') {
94	    const sessionId = /Messages from session ([^,]+),/.exec(told)?.[1];
95	    if (sessionId === LIAR_SESSION_ID) return json({ claims: [{ entryId: `${LIAR_SESSION_ID}:3`, quote: LIE, kind: 'tests_pass' }] });
96	    if (sessionId === HONEST_SESSION_ID) return json({ claims: [{ entryId: `${HONEST_SESSION_ID}:3`, quote: TRUTH, kind: 'tests_pass' }] });
97	    throw new Error(`extractor: could not find a session id in the prompt: ${told}`);
98	  }
99	
100	  if (req.role === 'judge') {
101	    if (told.includes('fact check for Dailies')) return json({ entailed: true });   // the ground stage's entailment check
102	    throw new Error(`judge: unexpected prompt (no 'implemented' claim should reach the diff judge): ${told}`);
103	  }
104	
105	  if (req.role === 'writer') {
106	    if (told.includes('Rewrite that one line')) throw new Error('writer: no rewrite should be needed — the scripted lines are grounded from the start');
107	    return json({
108	      scenes: [
109	        { type: 'prompt', entryId: `${LIAR_SESSION_ID}:0`, lines: [{ text: 'A developer asked the agent to fix a flaky test in the queue.', evidence: [{ type: 'entry', entryId: `${LIAR_SESSION_ID}:0` }] }] },
110	        { type: 'terminal', steps: [{ entryId: `${HONEST_SESSION_ID}:1` }], lines: [{ text: 'In the other session the agent ran the test suite and it passed.', evidence: [{ type: 'entry', entryId: `${HONEST_SESSION_ID}:2` }] }] },
111	      ],
112	    });
113	  }
114	
115	  throw new Error(`unexpected role: ${req.role}`);
116	}
117	
118	function readArtifact<T>(dataDir: string, runId: string, stage: string): T {
119	  return JSON.parse(readFileSync(join(dataDir, 'runs', runId, `${stage}.json`), 'utf8')) as T;
120	}
121	
122	function runIdFromVideoPath(videoPath: string): string {
123	  const match = /runs[/\\]([^/\\]+)[/\\]reel[/\\]reel\.mp4$/.exec(videoPath);
124	  if (!match) throw new Error(`could not read a run id out of ${videoPath}`);
125	  return match[1]!;
126	}
127	
128	describe('dailies run (end-to-end, mock model, real renderer)', () => {
129	  it('flags the lie, grounds the honest claim, and renders a reel awaiting approval', async () => {
130	    const repoDir = await fixtureRepo(liarAndHonestSessions());
131	    const dataDir = scratchDataDir();
132	    const lines: string[] = [];
133	
134	    const code = await runCommand([repoDir, '--since', '2026-10-09T00:00:00Z', '--no-review'], {
135	      client: createMockClient(reply),
136	      env: testEnv(dataDir),
137	      stdout: (line) => lines.push(line),
138	    });
139	
140	    expect(code).toBe(0);
141	    expect(lines).toContain('status: needs_approval');
142	
143	    const videoLine = lines.find((l) => l.startsWith('video: '));
144	    expect(videoLine).toBeDefined();
145	    const videoPath = videoLine!.slice('video: '.length);
146	    expect(existsSync(videoPath)).toBe(true);
147	
148	    const runId = runIdFromVideoPath(videoPath);
149	    const ground = readArtifact<GroundArtifact>(dataDir, runId, 'ground');
150	    expect(ground.storyboard.scenes.filter((s) => s.type === 'flag')).toHaveLength(1);
151	
152	    const render = readArtifact<{ durationSec: number }>(dataDir, runId, 'render');
153	    expect(render.durationSec).toBeGreaterThan(8);
154	
155	    const gate = readArtifact<GateArtifact>(dataDir, runId, 'gate');
156	    expect(gate.checks.every((c) => c.pass)).toBe(true);
157	    expect(gate.checks).toHaveLength(4);
158	  }, 90_000);
159	
160	  it('exits 2 with a clear message when the repository has no checkpoints', async () => {
161	    const repoDir = await fixtureRepo([]);
162	    const dataDir = scratchDataDir();
163	    const lines: string[] = [];
164	
165	    const code = await runCommand([repoDir, '--since', '2026-10-09T00:00:00Z'], {
166	      client: createMockClient(() => {
167	        throw new Error('no model call should happen before a repository with no checkpoints ends the run');
168	      }),
169	      env: testEnv(dataDir),
170	      stdout: (line) => lines.push(line),
171	    });
172	
173	    expect(code).toBe(2);
174	    expect(lines).toContain('reason: no agent sessions found in this window');
175	  });
176	
177	  it('dailies verify prints the contradicted and verified claims for the same fixture', async () => {
178	    const repoDir = await fixtureRepo(liarAndHonestSessions());
179	    const dataDir = scratchDataDir();
