  const colon = userinfo.indexOf(':');
  const parts = colon === -1 ? [userinfo] : [userinfo.slice(0, colon), userinfo.slice(colon + 1)];
  const decoded = parts.map((part) => {
    try {
      return decodeURIComponent(part);
    } catch {
